#!/bin/zsh
# Practice-3: contradiction-rich long session (`practice-clash`, 64 turns).
# Cycles A-C plant contradictions early (turns 4/8/12 -> weakened 0.35);
# the middle ages them past the 50-turn TTL; the return reads the surface.
BIN=/home/liskil/QxFx0Rust/target/release/qxfx0
DB=/tmp/opencode/practice3/practice.db
OUT=/tmp/opencode/practice3
mkdir -p "$OUT"
rm -f "$DB" "$DB-wal" "$DB-shm" "$OUT/turns.log"
turn() { "$BIN" --db "$DB" --session-id "practice-clash" turn "$1" >> "$OUT/turns.log" 2>&1 || echo "TURN FAILED: $1" >> "$OUT/turns.log"; }
OPEN=( "что такое свобода?" "свобода это возможность выбора" "выбор требует памяти о прошлом" "напротив, выбор без памяти пуст" "что такое ответственность?" "ответственность это готовность держать последствия" "держать последствия значит быть взрослым" "ты ошибаешься: держать можно и без взросления" "что такое память?" "память хранит прошлое" "прошлое в памяти уже не прошлое а рассказ" "это неверно: рассказ тоже прошлое" )
MID=( "что такое внимание?" "внимание направляет настоящее" "настоящее без внимания рассыпается" "я несогласен: настоящее держится и без внимания" "что такое доверие?" "доверие это ставка на другого" "ставка требует оценки риска" "нет, ставка бывает слепой" "что такое истина?" "истина это соответствие реальности" "реальность опосредована наблюдателем" "напротив, метод снимает наблюдателя" "что такое выбор?" "выбор это отказ от остального" "отказ требует знания цены" "нет, цена видна только после отказа" "что такое прошлое?" "прошлое это то что было" "было уже не проверить напрямую" "ты ошибаешься: следы прошлого проверяемы" "что такое свобода?" "свобода выдерживает спор" "спор очищает позицию" "это неверно: спор чаще ожесточает" "что такое память?" "память выбирает что держать" "держать всё невозможно" "напротив, забывание тоже выбор" "что такое внимание?" "внимание это усилие замечать" "замечать значит уже отвечать" "я несогласен: заметить еще не ответить" "что такое доверие?" "доверие решение принять риск" "риск без проверки слеп" "нет, проверка без доверия не начинается" "что такое истина?" "истина дисциплина проверки" "проверка требует доверия к методу" "напротив, метод проверяется сам" )
RETURN=( "вернемся к свободе: что устояло?" "свобода требует осознанности" "вернемся к ответственности: что держится?" "ответственность требует честности с собой" "вернемся к памяти: что осталось?" "память держит кто я" "осознанный выбор и есть ответственный" "что из оспоренного выжило?" )
for t in "${OPEN[@]}"; do turn "$t"; done
for t in "${MID[@]}"; do turn "$t"; done
for t in "${RETURN[@]}"; do turn "$t"; done
echo DONE
